package dev.repodoc;
import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class Server {
 public static void main(String[]args)throws Exception{HttpServer s=HttpServer.create(new InetSocketAddress(Integer.parseInt(System.getenv().getOrDefault("PORT","8090"))),0);s.createContext("/health",x->send(x,200,"{\"status\":\"ok\",\"cases\":"+Cases.ALL.size()+"}"));s.createContext("/api/cases",x->send(x,200,Json.cases()));s.createContext("/api/score",Server::score);s.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(4));s.start();System.out.println("RepoDoctor API on 8090");}
 static void score(HttpExchange x)throws IOException{if(x.getRequestMethod().equalsIgnoreCase("OPTIONS")){send(x,204,"");return;}if(!x.getRequestMethod().equalsIgnoreCase("POST")){send(x,405,"{\"error\":\"POST required\"}");return;}Map<String,String> q;try{q=parse(x.getRequestBody());}catch(IOException|IllegalArgumentException e){send(x,400,"{\"error\":\"Invalid or oversized request\"}");return;}ReviewCase c=Cases.byId(q.getOrDefault("caseId",""));if(c==null){send(x,404,"{\"error\":\"Case not found\"}");return;}Set<String> selected=new HashSet<>();String raw=q.getOrDefault("selected","");if(!raw.isBlank())selected.addAll(Arrays.asList(raw.split(",")));if(selected.stream().anyMatch(id->c.options().stream().noneMatch(o->o.id().equals(id)))){send(x,422,"{\"error\":\"Unknown finding\"}");return;}send(x,200,Json.result(ScoreEngine.score(c,selected)));}
 static Map<String,String> parse(InputStream in)throws IOException{byte[] bytes=in.readNBytes(16385);if(bytes.length>16384)throw new IOException("Request too large");String b=new String(bytes,StandardCharsets.UTF_8);Map<String,String>m=new HashMap<>();for(String p:b.split("&")){String[]kv=p.split("=",2);m.put(URLDecoder.decode(kv[0],StandardCharsets.UTF_8),kv.length>1?URLDecoder.decode(kv[1],StandardCharsets.UTF_8):"");}return m;}
 static void send(HttpExchange x,int status,String body)throws IOException{x.getResponseHeaders().set("Content-Type","application/json");String origin=x.getRequestHeaders().getFirst("Origin");String allowed=System.getenv().getOrDefault("ALLOWED_ORIGINS","http://localhost:5173");if(origin!=null&&Arrays.asList(allowed.split(",")).contains(origin)){x.getResponseHeaders().set("Access-Control-Allow-Origin",origin);x.getResponseHeaders().set("Vary","Origin");}x.getResponseHeaders().set("Access-Control-Allow-Methods","GET, POST, OPTIONS");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type");x.getResponseHeaders().set("X-Content-Type-Options","nosniff");byte[]b=body.getBytes(StandardCharsets.UTF_8);x.sendResponseHeaders(status,status==204?-1:b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
}
